parameters.jsonBody:
={
  "model": "gpt-4-turbo-preview",
  "messages": [
    {
      "role": "system",
      "content": "You are an expert crypto trader. Analyze market data and provide trading signals. Return JSON with: action (buy|sell|hold), confidence (0-1), reasoning, risk_level, suggested_entry_price, suggested_exit_price, stop_loss_price."
    },
    {
      "role": "user",
      "content": "Symbol: {{ $('PostgreSQL - Fetch Trading Config').item.json.symbol }}\nCurrent Price: {{ $json.price }}\nConfig: {{ JSON.stringify($('PostgreSQL - Fetch Trading Config').item.json) }}"
    }
  ],
  "temperature": 0.4,
  "response_format": { "type": "json_object" }
}

parameters.functionCode:
const signal = JSON.parse($input.item.json.choices[0].message.content);
const config = $('PostgreSQL - Fetch Trading Config').item.json;
const currentPrice = parseFloat($('Binance - Get Current Price').item.json.price);

const tradingDecision = {
  trade_id: `trade_${Date.now()}`,
  timestamp: new Date().toISOString(),
  symbol: config.symbol,
  current_price: currentPrice,
  ai_signal: signal,
  should_execute: signal.action !== 'hold' && signal.confidence >= 0.7,
  execution_params: {
    action: signal.action,
    quantity: signal.action === 'buy' ? (config.max_investment / currentPrice).toFixed(8) : null,
    limit_price: signal.suggested_entry_price || signal.suggested_exit_price,
    stop_loss: signal.stop_loss_price || config.stop_loss
  }
};

return { json: tradingDecision };

